"""Build the teaching draft and tiny, deterministic fixtures; does not publish."""
from pathlib import Path
import csv, io, json, random, sqlite3, time
from PIL import Image
from openpyxl import Workbook
ROOT = Path(__file__).resolve().parent
FIX = ROOT / 'fixtures'
FIX.mkdir(exist_ok=True)
bank=[]
chapters=[
 ('python-basics','Python basics','First steps: input, values, strings, collections, decisions, loops and a first function.'),
 ('python-strings-collections','Strings and collections','Practice indexing, methods, lists, tuples, dictionaries and sets after the basics.'),
 ('python-control-flow','Decisions, loops and comprehensions','Build from branching and iteration to counting, comprehensions and sentinel input.'),
 ('python-functions-modules','Functions and standard modules','Return values, default arguments, imports and small standard-library tools.'),
 ('python-files','Files and small reports','Read, write, append, organise and filter tiny local files; introduce exceptions.'),
 ('python-documents','Spreadsheets and documents','Read and create small Excel, Word and PDF files using supplied libraries.'),
 ('python-sqlite','Python and SQLite','Connect, query, insert and join using tiny local SQLite databases.'),
 ('python-web-data','Web data and HTML','Build URLs and parse saved JSON, XML and HTML responses without depending on external services.'),
 ('python-scientific-data','Scientific data and plots','Use NumPy, pandas, Biopython and matplotlib with small local datasets.'),
 ('python-images','Image processing','Inspect and transform tiny images, then introduce grayscale conversion and edge detection.')]
counts={c[1]:0 for c in chapters}

def fixture(name,content):
 p=FIX/'python-course'/name;p.parent.mkdir(parents=True,exist_ok=True)
 p.write_text(content,encoding='utf-8')
 return 'python-course/'+name

def tc(lines,expected='',**kw):
 return dict(input=[str(x) for x in lines],oracle=str(expected),**kw)

def e(ch,key,title,task,inputs,output,solution,tests,hint='',starter='',assumptions='All inputs satisfy the stated limits. Do not print input prompts.',difficulty='Easy',file_example=''):
 chapter=chapters[ch-1][1];counts[chapter]+=1
 first=tests[0]
 inp='\n'.join(first.get('input',[]))
 if first.get('arguments'):inp='Arguments: '+ ' '.join(first['arguments'])
 if first.get('functionTest'):inp=json.dumps(first['functionTest'],ensure_ascii=False)
 if not inp:inp='(no input)'
 example=first['oracle'] or '(no console output)'
 desc=f'### Task\n{task}\n\n### Input\n{inputs}\n\n### Output\n{output}\n\n### Assumptions\n{assumptions}\n\n### Example\nInput:\n```text\n{inp}\n```\nResult:\n```text\n{example}\n```'
 if file_example:desc+='\n\nGenerated file/content:\n```text\n'+file_example+'\n```'
 if hint:desc+='\n\n### Hint\n'+hint
 desc+='\n\nDifficulty: **'+difficulty.lower()+'**.'
 bank.append(dict(starter_code=starter.rstrip()+'\n' if starter else None,id=key if key in ['hello-world','python-input-output','python-string-operations','python-arithmetic','python-conditionals','python-lists','python-loops','python-functions','python-dictionaries','python-list-comprehension','python-first-excel-report','python-short-word-report','python-one-page-pdf-report','python-small-bar-chart','python-fetch-pfam-entry'] else 'python-'+key,title=title,language_id='python',chapter=chapter,order=counts[chapter],description=desc,solution=solution.rstrip()+'\n',testCases=tests))

# Chapter 1: each new operation is introduced on its own.
e(1,'hello-world','Hello, Python!','Print the message `Hello, Python!` exactly. `print()` displays text; text literals use quotes.','No input.','One line: `Hello, Python!`.','print("Hello, Python!")',[tc([],'Hello, Python!')],starter='# Add your print call here\n')
e(1,'python-input-output','A personalised greeting','Read a name into a variable and print `Hello, <name>!`. A variable stores a value for later use.','One complete line containing a name, possibly with spaces.','One greeting line.','name = input()\nprint(f"Hello, {name}!")',[tc(['Sam'],'Hello, Sam!'),tc(['Ada Lovelace'],'Hello, Ada Lovelace!'),tc(['Noor'],'Hello, Noor!')],hint='`input()` returns the whole line as text. An f-string inserts a variable using `{name}`.',starter='name = input()\n# Print the greeting using name\n')
e(1,'variables-two-inputs','Variables and two inputs','Read a sample name and its read count. A sample is simply a labelled measurement here. Convert the second input to an integer and print `<name>: <count> reads`.','Name on line 1; a non-negative integer on line 2.','One labelled count.','name = input()\ncount = int(input())\nprint(f"{name}: {count} reads")',[tc(['sample A',12],'sample A: 12 reads'),tc(['control',0],'control: 0 reads'),tc(['B',145],'B: 145 reads')],hint='`int(text)` converts a valid integer string.',starter='name = input()\ncount = int(input())\n# Print name and count\n')
e(1,'python-arithmetic','Add two numbers','Read two integers and print their sum.','Two integers, one per line.','The sum as an integer.','a = int(input())\nb = int(input())\nprint(a + b)',[tc([7,5],12),tc([0,0],0),tc([-8,3],-5)],starter='a = int(input())\nb = int(input())\n# Print their sum\n')
e(1,'minutes-seconds','Minutes and seconds','Convert a total number of seconds into whole minutes and remaining seconds.','One non-negative integer.','`<minutes> min <seconds> sec`.','seconds = int(input())\nprint(f"{seconds // 60} min {seconds % 60} sec")',[tc([125],'2 min 5 sec'),tc([0],'0 min 0 sec'),tc([60],'1 min 0 sec'),tc([59],'0 min 59 sec')],hint='`//` gives integer division; `%` gives the remainder.',starter='seconds = int(input())\n# Calculate minutes and remaining seconds\n')
e(1,'two-decimal-mean','A result with two decimals','Read two decimal measurements and print their arithmetic mean.','Two valid decimal numbers, one per line.','The mean with exactly two digits after the decimal point.','a = float(input())\nb = float(input())\nprint(f"{(a + b) / 2:.2f}")',[tc([2.5,4.0],'3.25'),tc([0,0],'0.00'),tc([-2.5,1.5],'-0.50')],hint='Use `float(input())` and formatting such as `f"{value:.2f}"`.',starter='a = float(input())\nb = float(input())\n# Calculate and format the mean\n')
e(1,'sequence-length','Sequence length','A DNA sequence is text made from letters such as A, C, G and T. Print the length of the supplied text.','One line; it may be empty.','The number of characters.','sequence = input()\nprint(len(sequence))',[tc(['ACGTA'],5),tc([''],0),tc(['T'],1)],hint='`len(text)` counts its characters.',starter='sequence = input()\n# Print its length\n')
e(1,'first-last-character','First and last character','Print the first and last characters of a string on separate lines.','One non-empty string.','First character, then last character.','text = input()\nprint(text[0])\nprint(text[-1])',[tc(['ACGT'],'A\nT'),tc(['G'],'G\nG'),tc(['sample'],'s\ne')],hint='Indexes start at 0. Index -1 selects the last character.',starter='text = input()\n# Print the first and last characters\n')
e(1,'small-slice','A small slice','Print the first three characters and last three characters of the input.','One string with at least six characters.','Two lines, each containing three characters.','text = input()\nprint(text[:3])\nprint(text[-3:])',[tc(['ACGTTG'],'ACG\nTTG'),tc(['ABCDEFGHI'],'ABC\nGHI'),tc(['123456'],'123\n456')],hint='A slice such as `text[:3]` stops before index 3.',starter='text = input()\n# Print two slices\n')
e(1,'python-string-operations','Clean a sample label','Remove spaces at the beginning and end, replace each remaining space with `_`, and convert the label to lowercase.','One non-empty label after removing outer spaces.','The cleaned label.','label = input()\nprint(label.strip().replace(" ", "_").lower())',[tc(['  Sample A  '],'sample_a'),tc(['CONTROL'],'control'),tc([' A  B '],'a__b')],hint='Combine `.strip()`, `.replace(" ", "_")` and `.lower()`.',starter='label = input()\n# Clean and print the label\n')
e(1,'python-lists','Make a list','Read three labels into a list, append a fourth label with `.append()`, and print each label in input order.','Four labels, one per line. Labels may contain spaces.','Four lines, one label per line.','labels = [input(), input(), input()]\nlabels.append(input())\nfor label in labels:\n    print(label)',[tc(['A','B','C','D'],'A\nB\nC\nD'),tc(['sample A','A','A','control'],'sample A\nA\nA\ncontrol'),tc(['one','two','three','four'],'one\ntwo\nthree\nfour')],hint='The supplied loop prints each list element. Complete the list creation and append step.',starter='labels = []\n# Read three labels into labels, then append the fourth\nfor label in labels:\n    print(label)\n')
e(1,'unpack-tuple','Unpack a tuple','Store a name and integer count in a tuple `(name, count)`, unpack it into two variables, and print both fields. A tuple groups values in a fixed sequence.','Name on line 1; non-negative integer count on line 2.','`name=<name>` and `count=<count>` on separate lines.','record = (input(), int(input()))\nname, count = record\nprint(f"name={name}")\nprint(f"count={count}")',[tc(['sample A',12],'name=sample A\ncount=12'),tc(['B',0],'name=B\ncount=0'),tc(['control',8],'name=control\ncount=8')],starter='record = (input(), int(input()))\n# Unpack record and print its fields\n')
e(1,'python-dictionaries','Look up a dictionary value','Use the dictionary in the starter to translate one DNA letter into its full name. Dictionaries associate keys with values.','One uppercase letter: A, C, G or T.','The corresponding full name.','bases = {"A": "adenine", "C": "cytosine", "G": "guanine", "T": "thymine"}\nprint(bases[input()])',[tc(['A'],'adenine'),tc(['G'],'guanine'),tc(['T'],'thymine'),tc(['C'],'cytosine')],hint='Access a value with `bases[key]`.',starter='bases = {"A": "adenine", "C": "cytosine", "G": "guanine", "T": "thymine"}\nkey = input()\n# Print the value for key\n')
e(1,'unique-labels','Count unique labels','Split a line into labels and print how many distinct labels it contains. A set retains each distinct value once.','One whitespace-separated line of labels; it may be empty.','The number of distinct labels.','labels = input().split()\nprint(len(set(labels)))',[tc(['s1 s2 s1'],2),tc([''],0),tc(['A A A'],1),tc(['A B C'],3)],hint='`input().split()` makes a list. `set(labels)` removes duplicates.',starter='labels = input().split()\n# Count distinct labels\n')
e(1,'limit-check','Above or below the limit','Print `pass` if the count is at least 10; otherwise print `fail`. Use an `if`/`else` decision.','One non-negative integer.','Exactly `pass` or `fail`.','count = int(input())\nif count >= 10:\n    print("pass")\nelse:\n    print("fail")',[tc([9],'fail'),tc([10],'pass'),tc([11],'pass'),tc([0],'fail')],hint='Indent the statements inside each branch by four spaces.',starter='count = int(input())\n# Add an if/else decision\n')
e(1,'python-loops','Print a numbered range','Use a `for` loop to print all integers from 1 through n, inclusive.','One integer n between 0 and 20.','One integer per line. If n is 0, print nothing.','n = int(input())\nfor number in range(1, n + 1):\n    print(number)',[tc([3],'1\n2\n3'),tc([0],''),tc([1],'1')],hint='`range(start, stop)` excludes stop.',starter='n = int(input())\n# Loop over the required range\n')
e(1,'countdown','A countdown','Use a `while` loop to print the input number down to 0, inclusive.','One integer between 0 and 20.','One number per line, in descending order.','number = int(input())\nwhile number >= 0:\n    print(number)\n    number -= 1',[tc([3],'3\n2\n1\n0'),tc([0],'0'),tc([1],'1\n0')],hint='Decrease the number inside the loop so the condition eventually becomes false.',starter='number = int(input())\n# Write a while loop and update number\n')
e(1,'python-functions','Your first function','Complete `double(value)` so it returns twice its argument. Keep the caller below it. `return` sends a value back to the calling code.','One integer from stdin.','The returned integer, printed by the caller.','def double(value):\n    return value * 2\n\nvalue = int(input())\nprint(double(value))',[tc([6],12),tc([0],0),tc([-4],-8)],starter='def double(value):\n    # Replace pass with a return statement\n    pass\n\nvalue = int(input())\nprint(double(value))\n')

# Chapter 2.
e(2,'every-third-character','Every third character','Print every third character starting at index 0, then the reversed input.','One string, possibly empty.','Two lines: stepped slice and reversed string. Empty slices are empty lines.','text = input()\nprint(text[::3])\nprint(text[::-1])',[tc(['ABCDEFG'],'ADG\nGFEDCBA'),tc(['X'],'X\nX'),tc([''],'\n')],hint='Use `text[::3]` and a negative slice step.')
e(2,'sample-prefix','Find a sample prefix','Find the first occurrence of a substring. Print its one-based position, or `not found` if absent.','Label on line 1; non-empty substring on line 2.','A position starting at 1, or `not found`.','label = input()\nneedle = input()\nindex = label.find(needle)\nprint(index + 1 if index >= 0 else "not found")',[tc(['sample_A','_'],7),tc(['ABABA','AB'],1),tc(['sample','X'],'not found'),tc(['ABABA','BA'],2)],hint='`.find()` returns -1 when absent; Python indexes themselves start at 0.')
e(2,'merge-lists','Merge two lists','Extend the first list with the second, preserving order and duplicates.','Two lines of whitespace-separated labels; either line may be empty.','All labels joined by one space, or an empty line if both lists are empty.','first = input().split()\nfirst.extend(input().split())\nprint(" ".join(first))',[tc(['A B','B C'],'A B B C'),tc(['','X'],'X'),tc(['',''],'')],hint='Use `.extend()` to add all elements and `" ".join(labels)` to make text.')
e(2,'measurement-record','Parse a measurement record','Split `sample,count,group` into three fields and unpack them. Print a sentence using those fields.','One line with exactly three comma-separated fields. Count is an integer; fields contain no commas or outer spaces.','`<sample> belongs to <group> and has <count> reads`.','sample, count, group = input().split(",")\nprint(f"{sample} belongs to {group} and has {int(count)} reads")',[tc(['A,12,treated'],'A belongs to treated and has 12 reads'),tc(['control sample,0,control'],'control sample belongs to control and has 0 reads'),tc(['B,8,treated'],'B belongs to treated and has 8 reads')],hint='This is a simple split task. Quoted CSV fields are introduced in the files chapter.',difficulty='Medium')
e(2,'update-inventory','Update a small inventory','Start with `{"tube": 3, "plate": 2}`. Add the supplied increment to the existing item. Print both entries in alphabetical key order.','Item (`tube` or `plate`) on line 1; non-negative integer increment on line 2.','One `<item>: <count>` line per key.','inventory = {"tube": 3, "plate": 2}\nitem = input()\ninventory[item] += int(input())\nfor key in sorted(inventory):\n    print(f"{key}: {inventory[key]}")',[tc(['tube',4],'plate: 2\ntube: 7'),tc(['plate',0],'plate: 2\ntube: 3'),tc(['plate',5],'plate: 7\ntube: 3')],hint='`sorted(dictionary)` returns its keys in order.',starter='inventory = {"tube": 3, "plate": 2}\n# Read and update an item, then print both entries\n',difficulty='Medium')
e(2,'shared-labels','Shared sample labels','Treat both lists as sets. Print their intersection, then their union, sorting each alphabetically.','Two whitespace-separated lines of labels; duplicates and empty lines are allowed.','Two lines. Each is labels joined by spaces, or `none` if empty.','first = set(input().split())\nsecond = set(input().split())\nprint(" ".join(sorted(first & second)) or "none")\nprint(" ".join(sorted(first | second)) or "none")',[tc(['B A A','B C'],'B\nA B C'),tc(['A','C'],'none\nA C'),tc(['',''],'none\nnone')],hint='`&` is intersection and `|` is union.',difficulty='Medium')
