e(3,'python-conditionals','Classify a measurement','Print `low` below 10, `normal` from 10 through 20 inclusive, and `high` above 20.','One integer.','One classification word.','value = int(input())\nif value < 10:\n    print("low")\nelif value <= 20:\n    print("normal")\nelse:\n    print("high")',[tc([9],'low'),tc([10],'normal'),tc([20],'normal'),tc([21],'high')],hint='Use `elif` for the middle branch.')
e(3,'number-samples','Number the samples','Print each label with its position, starting at 1. Use `enumerate()`.','One whitespace-separated line of labels, possibly empty.','One `<position>: <label>` line per label; no output for an empty list.','for index, label in enumerate(input().split(), start=1):\n    print(f"{index}: {label}")',[tc(['A B C'],'1: A\n2: B\n3: C'),tc([''],''),tc(['A A'],'1: A\n2: A')],hint='`enumerate(labels, start=1)` supplies both position and value.')
e(3,'count-labels','Count label occurrences','Count each distinct label using a dictionary. Print labels alphabetically with their frequencies.','One whitespace-separated line; it may be empty.','One `<label>: <count>` line per distinct label; no output for an empty list.','counts = {}\nfor label in input().split():\n    counts[label] = counts.get(label, 0) + 1\nfor label in sorted(counts):\n    print(f"{label}: {counts[label]}")',[tc(['s2 s1 s2'],'s1: 1\ns2: 2'),tc([''],''),tc(['A A A B'],'A: 3\nB: 1')],hint='`counts.get(label, 0)` supplies zero before a key has been added.',difficulty='Medium')
e(3,'skip-stop','Skip comments, stop at END','Read n and then n supplied lines. Skip lines beginning with `#`. Print other lines until a line equals `END`, then stop. Use `continue` and `break`.','n (0–10) on line 1, followed by exactly n lines. No trimming: `#` must be the first character and END must match the whole line.','Retained lines in input order. Nothing after END is printed.','n = int(input())\nfor _ in range(n):\n    line = input()\n    if line == "END":\n        break\n    if line.startswith("#"):\n        continue\n    print(line)',[tc([5,'# note','A','B','END','C'],'A\nB'),tc([0],''),tc([3,'A','#skip','B'],'A\nB'),tc([2,'END','A'],'')],difficulty='Medium')
e(3,'python-list-comprehension','Transform measurements','Use a list comprehension to square only the strictly positive integers, preserving their input order.','One whitespace-separated line of integers, possibly empty.','Squares joined by spaces, or `none` if there are none.','values = [int(value) for value in input().split()]\nsquares = [value ** 2 for value in values if value > 0]\nprint(" ".join(map(str, squares)) or "none")',[tc(['-2 0 3 4'],'9 16'),tc(['-1 0'],'none'),tc([''],'none'),tc(['2 2 1'],'4 4 1')],hint='A comprehension can end with an `if` condition.',difficulty='Medium')
e(3,'two-comprehensions','Build two comprehensions','Build a dictionary mapping labels to lengths and a set of distinct lengths using comprehensions. Print the dictionary by alphabetical key, then sorted lengths.','One line of unique whitespace-separated labels, possibly empty.','`<label>:<length>` lines followed by `lengths: <numbers joined by spaces>`, or `lengths: none`.','labels = input().split()\nlengths = {label: len(label) for label in labels}\ndistinct = {len(label) for label in labels}\nfor label in sorted(lengths):\n    print(f"{label}:{lengths[label]}")\nprint("lengths: " + (" ".join(map(str, sorted(distinct))) or "none"))',[tc(['BB A CCC'],'A:1\nBB:2\nCCC:3\nlengths: 1 2 3'),tc([''],'lengths: none'),tc(['BB AA'],'AA:2\nBB:2\nlengths: 2')],hint='Dictionary: `{key: value for ...}`. Set: `{value for ...}`.',difficulty='Medium')
e(3,'running-total','A running total','Read integers until 0. Count and sum the preceding integers; exclude the terminating 0.','Integers, one per line. A terminating 0 is always supplied.','`count: <count>` then `total: <sum>`.','count = 0\ntotal = 0\nwhile True:\n    value = int(input())\n    if value == 0:\n        break\n    count += 1\n    total += value\nprint(f"count: {count}")\nprint(f"total: {total}")',[tc([5,-2,0],'count: 2\ntotal: 3'),tc([0],'count: 0\ntotal: 0'),tc([-3,3,2,0],'count: 3\ntotal: 2')],hint='Initialise both accumulators before the loop.',difficulty='Harder')
