e(8,'html-links','Extract links from saved HTML','Use Beautiful Soup with the built-in `html.parser` to select anchors with an href attribute. For each, print its visible text, then its href, separated by ` | `. Use `get_text(" ", strip=True)` for text. Preserve document order and duplicate links.','One UTF-8 HTML filename.','`<text> | <href>` per matching anchor, or `none` if none exist.','from bs4 import BeautifulSoup\nwith open(input(), encoding="utf-8") as source:\n    soup = BeautifulSoup(source.read(), "html.parser")\nlinks = soup.select("a[href]")\nfor link in links:\n    print(f"{link.get_text(\' \', strip=True)} | {link[\'href\']}")\nif not links:\n    print("none")',[tc([html_a],'Entry A | /entry/A\nEntry B | https://example.org/B',fixtures=[html_a]),tc([html_b],'none',fixtures=[html_b]),tc([html_c],'One | /one\nAgain | /one',fixtures=[html_c])],hint='Supplied HTML keeps this task reproducible; `.select("a[href]")` skips anchors without an href.',difficulty='Medium')
