e(9,'python-small-bar-chart','Plot small group counts','Count rows belonging to groups A and B in the CSV, including zero for an absent group. Save a bar chart as counts.png. Use matplotlib defaults, a 4 × 3 inch figure at 100 DPI, bars A then B, title `Sample counts`, x-label `Sample`, y-label `Count`, and y-limits 0 to max(counts)+1. Call tight_layout before saving; close afterward.','One CSV filename with sample,group columns; group is A or B. Header-only CSV is allowed.','Print `Counts: <A>, <B>` and create a 400 × 300 pixel counts.png. The values and chart appearance are graded; small rendering differences are tolerated.','import csv\nimport matplotlib.pyplot as plt\ncounts = {"A": 0, "B": 0}\nwith open(input(), newline="", encoding="utf-8") as source:\n    for row in csv.DictReader(source):\n        counts[row["group"]] += 1\nvalues = [counts["A"], counts["B"]]\nprint(f"Counts: {values[0]}, {values[1]}")\nplt.figure(figsize=(4, 3), dpi=100)\nplt.bar(["A", "B"], values)\nplt.title("Sample counts")\nplt.xlabel("Sample")\nplt.ylabel("Count")\nplt.ylim(0, max(values) + 1)\nplt.tight_layout()\nplt.savefig("counts.png")\nplt.close()',[tc([plot_a],'Counts: 2, 3',fixtures=[plot_a],outputFiles=['counts.png'],artifactChecks=plotcheck),tc([plot_b],'Counts: 0, 2',fixtures=[plot_b],outputFiles=['counts.png'],artifactChecks=plotcheck),tc([plot_c],'Counts: 0, 0',fixtures=[plot_c],outputFiles=['counts.png'],artifactChecks=plotcheck)],hint='A display window is unnecessary. Keep default colours/width/style and use `plt.figure`, `plt.bar`, `plt.title`, `plt.xlabel`, `plt.ylabel`, `plt.ylim`, `plt.tight_layout` and `plt.savefig`.',starter='import csv\nimport matplotlib.pyplot as plt\n# Count the rows for A and B\n# Print the counts, create the specified chart, save and close\n',difficulty='Harder',file_example='counts.png: bars A=2 and B=3, with the specified title and axis labels')
# Chapter 10 synthetic images.
for name,w,h,mode in [('rgb-a.png',6,4,'RGB'),('rgb-b.png',4,6,'RGB'),('gray.png',5,3,'L')]:
 image=Image.new(mode,(w,h))
 for y in range(h):
  for x in range(w):image.putpixel((x,y),((x*41)%256,(y*61)%256,((x+y)*29)%256) if mode=='RGB' else (x*30+y*20)%256)
 image.save(FIX/'python-course'/name)
for name,size,box in [('square-a.png',16,(4,4,12,12)),('square-b.png',20,(5,5,15,15)),('square-blank.png',16,None)]:
 im=Image.new('L',(size,size),0)
 if box:
  for y in range(box[1],box[3]):
   for x in range(box[0],box[2]):im.putpixel((x,y),255)
 im.save(FIX/'python-course'/name)
