e(10,'flip-rotate','Flip and rotate','From the original image, save a left-right flip as flipped.png and a 90-degree counterclockwise rotation as rotated.png. Perform both operations independently on the original.','One PNG filename. Fixtures are asymmetric so direction matters.','Create flipped.png and rotated.png; print nothing. Dimensions and pixels are graded.','from PIL import Image\nwith Image.open(input()) as image:\n    image.transpose(Image.Transpose.FLIP_LEFT_RIGHT).save("flipped.png")\n    image.transpose(Image.Transpose.ROTATE_90).save("rotated.png")',[tc([f],fixtures=[f],outputFiles=['flipped.png','rotated.png'],artifactChecks=[{'filename':'flipped.png','kind':'image'},{'filename':'rotated.png','kind':'image'}]) for f in [img_a,img_b,img_g]],hint='Use `Image.Transpose.FLIP_LEFT_RIGHT` and `Image.Transpose.ROTATE_90` with `.transpose()`.',difficulty='Medium',file_example='flipped.png: 6 × 4 pixels, mirrored horizontally\nrotated.png: 4 × 6 pixels, rotated counterclockwise')
e(10,'thumbnail','Make a thumbnail','Use Pillow `.thumbnail()` with `Image.Resampling.LANCZOS` to fit the image inside the supplied maximum size, keeping its aspect ratio and never enlarging it. Save thumbnail.png.','PNG filename on line 1; positive maximum width and height on line 2.','Create thumbnail.png; print nothing. The platform compares dimensions and pixels produced by this specified Pillow operation.','from PIL import Image\nfilename = input()\nsize = tuple(int(value) for value in input().split())\nwith Image.open(filename) as image:\n    image.thumbnail(size, resample=Image.Resampling.LANCZOS)\n    image.save("thumbnail.png")',[tc([img_a,'3 3'],fixtures=[img_a],outputFiles=['thumbnail.png'],artifactChecks=[{'filename':'thumbnail.png','kind':'image'}]),tc([img_b,'2 2'],fixtures=[img_b],outputFiles=['thumbnail.png'],artifactChecks=[{'filename':'thumbnail.png','kind':'image'}]),tc([img_a,'20 20'],fixtures=[img_a],outputFiles=['thumbnail.png'],artifactChecks=[{'filename':'thumbnail.png','kind':'image'}])],hint='`.thumbnail()` changes the image in place. Pillow chooses integer dimensions preserving the ratio as closely as possible.',difficulty='Medium',file_example='thumbnail.png: 3 × 2 pixels for the 6 × 4 input and 3 × 3 maximum')
# Values use the documented rgb2gray coefficients; verify against the pinned runtime.
gray_tests=[]
for f in [img_a,img_b]:
 with Image.open(FIX/f) as im:
  p0=im.getpixel((0,0));p1=im.getpixel((1,1));h=im.height;w=im.width
  val=lambda p:sum(a*b for a,b in zip(p,[0.2125,0.7154,0.0721]))/255
  gray_tests.append(tc([f],f'shape: ({h}, {w})\npixel(0,0): {val(p0):.4f}\npixel(1,1): {val(p1):.4f}',fixtures=[f]))
